### Implementation Steps

**Phase 1: Lifecycle Framework Foundation (Weeks 1-3)**

**Step 1.1: Define Lifecycle States and Transitions**

```yaml
# tenant-lifecycle-states.yaml
states:

  - name: "pending"
    description: "Tenant requested, awaiting approval"
    allowed_transitions: ["approved", "rejected"]

  - name: "provisioning"
    description: "Infrastructure and configuration being created"
    allowed_transitions: ["active", "failed"]

  - name: "active"
    description: "Tenant operational and accessible"
    allowed_transitions: ["suspended", "maintenance", "terminating"]

  - name: "suspended"
    description: "Tenant access temporarily disabled"
    allowed_transitions: ["active", "terminating"]

  - name: "maintenance"
    description: "Scheduled maintenance window"
    allowed_transitions: ["active"]

  - name: "terminating"
    description: "Offboarding in progress"
    allowed_transitions: ["archived"]

  - name: "archived"
    description: "Tenant decommissioned, data archived"
    allowed_transitions: ["deleted"]

  - name: "deleted"
    description: "Tenant and data permanently deleted"
    allowed_transitions: []

transition_rules:

  - from: "active"
    to: "suspended"
    automated: true
    triggers: ["payment_failure", "compliance_violation", "voluntary_suspension"]
    notifications: ["tenant_admin", "support_team"]

  - from: "suspended"
    to: "active"
    automated: false
    approval_required: true
    approvers: ["operations_manager"]
    validation_checks: ["payment_resolved", "compliance_restored"]
```

**Step 1.2: Implement Tenant Lifecycle Repository**

```csharp
// TenantLifecycleRepository.cs
public class TenantLifecycleRepository
{
    private readonly DbContext _context;
    private readonly IAuditLogger _auditLogger;

    public async Task<TenantLifecycleRecord> GetLifecycleAsync(string tenantId)
    {
        return await _context.TenantLifecycles
            .Include(t => t.StatusHistory)
            .Include(t => t.OnboardingMetadata)
            .FirstOrDefaultAsync(t => t.TenantId == tenantId);
    }

    public async Task<TenantLifecycleRecord> CreateLifecycleAsync(
        TenantRequest request)
    {
        var lifecycle = new TenantLifecycleRecord
        {
            TenantId = Guid.NewGuid().ToString(),
            Name = request.Name,
            Tier = request.Tier,
            Status = TenantStatus.Pending,
            RequestedDate = DateTime.UtcNow,
            RequestedBy = request.RequestedBy,
            RequiredApprovals = request.Tier == "enterprise"
                ? new[] { "sales", "legal", "security", "operations" }
                : new[] { "sales", "operations" },
            Metadata = request.Metadata
        };

        _context.TenantLifecycles.Add(lifecycle);
        await _context.SaveChangesAsync();

        await _auditLogger.LogEventAsync(new AuditEvent
        {
            TenantId = lifecycle.TenantId,
            EventType = "tenant_requested",
            Timestamp = DateTime.UtcNow,
            Actor = request.RequestedBy,
            Details = lifecycle
        });

        return lifecycle;
    }

    public async Task RecordStatusChangeAsync(
        string tenantId,
        TenantStatus newStatus,
        string reason,
        string changedBy)
    {
        var lifecycle = await GetLifecycleAsync(tenantId);
        var previousStatus = lifecycle.Status;

        lifecycle.Status = newStatus;
        lifecycle.StatusHistory.Add(new StatusHistoryEntry
        {
            Status = newStatus,
            Timestamp = DateTime.UtcNow,
            Reason = reason,
            ChangedBy = changedBy,
            PreviousStatus = previousStatus
        });

        await _context.SaveChangesAsync();

        await _auditLogger.LogEventAsync(new AuditEvent
        {
            TenantId = tenantId,
            EventType = "status_changed",
            Timestamp = DateTime.UtcNow,
            Actor = changedBy,
            Details = new
            {
                PreviousStatus = previousStatus,
                NewStatus = newStatus,
                Reason = reason
            }
        });
    }
}

public class TenantLifecycleRecord
{
    public string TenantId { get; set; }
    public string Name { get; set; }
    public string Tier { get; set; }
    public TenantStatus Status { get; set; }
    public DateTime RequestedDate { get; set; }
    public string RequestedBy { get; set; }
    public DateTime? ActivatedDate { get; set; }
    public DateTime? SuspendedDate { get; set; }
    public DateTime? TerminatedDate { get; set; }
    public DateTime? ArchivedDate { get; set; }
    public DateTime? DeletedDate { get; set; }
    public string[] RequiredApprovals { get; set; }
    public Dictionary<string, ApprovalRecord> Approvals { get; set; }
    public List<StatusHistoryEntry> StatusHistory { get; set; }
    public Dictionary<string, object> OnboardingMetadata { get; set; }
    public Dictionary<string, object> Metadata { get; set; }
}

public enum TenantStatus
{
    Pending,
    Provisioning,
    Active,
    Suspended,
    Maintenance,
    Terminating,
    Archived,
    Deleted
}
```

**Step 1.3: Build Status Workflow Engine**

```csharp
// TenantStatusWorkflowEngine.cs
public class TenantStatusWorkflowEngine
{
    private readonly TenantLifecycleRepository _lifecycleRepo;
    private readonly INotificationService _notificationService;
    private readonly ITenantAccessController _accessController;
    private readonly ILogger<TenantStatusWorkflowEngine> _logger;

    public async Task<StatusTransitionResult> TransitionStatusAsync(
        string tenantId,
        TenantStatus newStatus,
        string reason,
        string actor,
        bool force = false)
    {
        var lifecycle = await _lifecycleRepo.GetLifecycleAsync(tenantId);
        var currentStatus = lifecycle.Status;

        // Validate transition is allowed
        if (!IsTransitionAllowed(currentStatus, newStatus) && !force)
        {
            return StatusTransitionResult.Failure(
                $"Transition from {currentStatus} to {newStatus} not allowed");
        }

        try
        {
            // Execute pre-transition actions
            await ExecutePreTransitionActionsAsync(
                tenantId, currentStatus, newStatus);

            // Update status in repository
            await _lifecycleRepo.RecordStatusChangeAsync(
                tenantId, newStatus, reason, actor);

            // Execute post-transition actions
            await ExecutePostTransitionActionsAsync(
                tenantId, currentStatus, newStatus);

            // Send notifications
            await SendTransitionNotificationsAsync(
                tenantId, currentStatus, newStatus, reason);

            _logger.LogInformation(
                "Tenant {TenantId} transitioned from {OldStatus} to {NewStatus}",
                tenantId, currentStatus, newStatus);

            return StatusTransitionResult.Success(newStatus);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Failed to transition tenant {TenantId} to {NewStatus}",
                tenantId, newStatus);
            return StatusTransitionResult.Failure(ex.Message);
        }
    }

    private async Task ExecutePostTransitionActionsAsync(
        string tenantId,
        TenantStatus oldStatus,
        TenantStatus newStatus)
    {
        switch (newStatus)
        {
            case TenantStatus.Active:
                if (oldStatus == TenantStatus.Provisioning)
                {
                    // First activation
                    await _accessController.EnableAccessAsync(tenantId);
                    await _notificationService.SendWelcomeEmailAsync(tenantId);
                }
                else if (oldStatus == TenantStatus.Suspended)
                {
                    // Reactivation
                    await _accessController.EnableAccessAsync(tenantId);
                }
                break;

            case TenantStatus.Suspended:
                await _accessController.DisableAccessAsync(tenantId);
                await _notificationService.SendSuspensionNoticeAsync(
                    tenantId, GetSuspensionReason(tenantId));
                break;

            case TenantStatus.Maintenance:
                await _accessController.SetMaintenanceModeAsync(tenantId);
                break;

            case TenantStatus.Terminating:
                await _accessController.DisableAccessAsync(tenantId);
                await StartOffboardingWorkflowAsync(tenantId);
                break;
        }
    }

    private bool IsTransitionAllowed(
        TenantStatus current, TenantStatus target)
    {
        var allowedTransitions = new Dictionary<TenantStatus, TenantStatus[]>
        {
            [TenantStatus.Pending] = new[]
                { TenantStatus.Provisioning },
            [TenantStatus.Provisioning] = new[]
                { TenantStatus.Active, TenantStatus.Pending },
            [TenantStatus.Active] = new[]
                { TenantStatus.Suspended, TenantStatus.Maintenance, TenantStatus.Terminating },
            [TenantStatus.Suspended] = new[]
                { TenantStatus.Active, TenantStatus.Terminating },
            [TenantStatus.Maintenance] = new[]
                { TenantStatus.Active },
            [TenantStatus.Terminating] = new[]
                { TenantStatus.Archived },
            [TenantStatus.Archived] = new[]
                { TenantStatus.Deleted }
        };

        return allowedTransitions.ContainsKey(current) &&
               allowedTransitions[current].Contains(target);
    }
}
