**Phase 2: Onboarding Automation (Weeks 4-7)**

**Step 2.1: Implement Approval Workflow**

```csharp
// TenantApprovalWorkflowService.cs
public class TenantApprovalWorkflowService
{
    private readonly TenantLifecycleRepository _lifecycleRepo;
    private readonly INotificationService _notificationService;
    private readonly IWorkflowEngine _workflowEngine;

    public async Task<ApprovalWorkflowResult> StartApprovalWorkflowAsync(
        string tenantId)
    {
        var lifecycle = await _lifecycleRepo.GetLifecycleAsync(tenantId);
        var requiredApprovals = lifecycle.RequiredApprovals;

        // Create approval workflow
        var workflowId = await _workflowEngine.CreateWorkflowAsync(
            "tenant-approval",
            new
            {
                TenantId = tenantId,
                RequiredApprovals = requiredApprovals,
                Timeout = TimeSpan.FromDays(7)
            });

        // Send approval requests
        foreach (var approver in requiredApprovals)
        {
            await _notificationService.SendApprovalRequestAsync(
                tenantId, approver, workflowId);
        }

        return new ApprovalWorkflowResult
        {
            WorkflowId = workflowId,
            Status = "pending",
            RequiredApprovals = requiredApprovals
        };
    }

    public async Task<ApprovalResult> RecordApprovalAsync(
        string tenantId,
        string approver,
        bool approved,
        string comments)
    {
        var lifecycle = await _lifecycleRepo.GetLifecycleAsync(tenantId);

        if (lifecycle.Approvals == null)
            lifecycle.Approvals = new Dictionary<string, ApprovalRecord>();

        lifecycle.Approvals[approver] = new ApprovalRecord
        {
            Approver = approver,
            Approved = approved,
            Timestamp = DateTime.UtcNow,
            Comments = comments
        };

        await _lifecycleRepo.UpdateLifecycleAsync(lifecycle);

        // Check if all approvals received
        var allApproved = lifecycle.RequiredApprovals.All(a =>
            lifecycle.Approvals.ContainsKey(a) &&
            lifecycle.Approvals[a].Approved);

        var anyRejected = lifecycle.Approvals.Values.Any(a => !a.Approved);

        if (anyRejected)
        {
            await _lifecycleRepo.RecordStatusChangeAsync(
                tenantId,
                TenantStatus.Pending,
                $"Rejected by {approver}",
                approver);

            return ApprovalResult.Rejected(approver, comments);
        }

        if (allApproved)
        {
            // All approvals received, start provisioning
            await StartProvisioningAsync(tenantId);
            return ApprovalResult.FullyApproved();
        }

        return ApprovalResult.PartiallyApproved(
            lifecycle.Approvals.Count,
            lifecycle.RequiredApprovals.Length);
    }

    private async Task StartProvisioningAsync(string tenantId)
    {
        await _lifecycleRepo.RecordStatusChangeAsync(
            tenantId,
            TenantStatus.Provisioning,
            "All approvals received",
            "system");

        // Trigger provisioning orchestrator
        await _workflowEngine.StartWorkflowAsync(
            "tenant-provisioning",
            new { TenantId = tenantId });
    }
}
