**Step 2.2: Build Provisioning Orchestrator**

```csharp
// TenantProvisioningOrchestrator.cs
public class TenantProvisioningOrchestrator
{
    private readonly IInfrastructureProvisioner _infraProvisioner;
    private readonly IDatabaseProvisioner _dbProvisioner;
    private readonly ISecurityProvisioner _securityProvisioner;
    private readonly IConfigurationDeployer _configDeployer;
    private readonly IValidationService _validator;
    private readonly TenantLifecycleRepository _lifecycleRepo;

    public async Task<ProvisioningResult> ProvisionTenantAsync(
        string tenantId)
    {
        var provisioningContext = new ProvisioningContext
        {
            TenantId = tenantId,
            StartTime = DateTime.UtcNow,
            Steps = new List<ProvisioningStep>()
        };

        try
        {
            // Step 1: Provision infrastructure
            await ExecuteStepAsync(provisioningContext,
                "infrastructure",
                async () => await _infraProvisioner.ProvisionAsync(tenantId));

            // Step 2: Provision database
            await ExecuteStepAsync(provisioningContext,
                "database",
                async () => await _dbProvisioner.ProvisionDatabaseAsync(tenantId));

            // Step 3: Setup security (keys, certificates, access controls)
            await ExecuteStepAsync(provisioningContext,
                "security",
                async () => await _securityProvisioner.SetupSecurityAsync(tenantId));

            // Step 4: Deploy configuration
            await ExecuteStepAsync(provisioningContext,
                "configuration",
                async () => await _configDeployer.DeployConfigurationAsync(tenantId));

            // Step 5: Validate provisioning
            await ExecuteStepAsync(provisioningContext,
                "validation",
                async () => await _validator.ValidateProvisioningAsync(tenantId));

            // Step 6: Activate tenant
            await _lifecycleRepo.RecordStatusChangeAsync(
                tenantId,
                TenantStatus.Active,
                "Provisioning completed successfully",
                "system");

            provisioningContext.CompletedSuccessfully = true;
            provisioningContext.EndTime = DateTime.UtcNow;

            return ProvisioningResult.Success(provisioningContext);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Provisioning failed for tenant {TenantId} at step {Step}",
                tenantId, provisioningContext.CurrentStep);

            // Attempt rollback
            await RollbackProvisioningAsync(provisioningContext);

            await _lifecycleRepo.RecordStatusChangeAsync(
                tenantId,
                TenantStatus.Pending,
                $"Provisioning failed: {ex.Message}",
                "system");

            return ProvisioningResult.Failure(ex.Message, provisioningContext);
        }
    }

    private async Task ExecuteStepAsync(
        ProvisioningContext context,
        string stepName,
        Func<Task<StepResult>> stepAction)
    {
        context.CurrentStep = stepName;
        var step = new ProvisioningStep
        {
            Name = stepName,
            StartTime = DateTime.UtcNow
        };

        try
        {
            var result = await stepAction();
            step.Succeeded = result.Success;
            step.EndTime = DateTime.UtcNow;
            step.Result = result;
            context.Steps.Add(step);

            if (!result.Success)
            {
                throw new ProvisioningException(
                    $"Step {stepName} failed: {result.ErrorMessage}");
            }
        }
        catch (Exception ex)
        {
            step.Succeeded = false;
            step.EndTime = DateTime.UtcNow;
            step.Error = ex.Message;
            context.Steps.Add(step);
            throw;
        }
    }

    private async Task RollbackProvisioningAsync(
        ProvisioningContext context)
    {
        // Rollback in reverse order
        for (int i = context.Steps.Count - 1; i >= 0; i--)
        {
            var step = context.Steps[i];
            if (!step.Succeeded) continue;

            try
            {
                switch (step.Name)
                {
                    case "configuration":
                        await _configDeployer.RollbackConfigurationAsync(
                            context.TenantId);
                        break;
                    case "security":
                        await _securityProvisioner.CleanupSecurityAsync(
                            context.TenantId);
                        break;
                    case "database":
                        await _dbProvisioner.DeleteDatabaseAsync(
                            context.TenantId);
                        break;
                    case "infrastructure":
                        await _infraProvisioner.DeprovisionAsync(
                            context.TenantId);
                        break;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex,
                    "Rollback failed for step {Step} of tenant {TenantId}",
                    step.Name, context.TenantId);
            }
        }
    }
}
