**Phase 3: Offboarding and Data Retention (Weeks 8-10)**

**Step 3.1: Implement Offboarding Service**

```csharp
// TenantOffboardingService.cs
public class TenantOffboardingService
{
    private readonly TenantLifecycleRepository _lifecycleRepo;
    private readonly ITenantAccessController _accessController;
    private readonly IDataArchivalService _archivalService;
    private readonly IResourceCleanupService _cleanupService;
    private readonly INotificationService _notificationService;
    private readonly IAuditLogger _auditLogger;

    public async Task<OffboardingResult> InitiateOffboardingAsync(
        string tenantId,
        string reason,
        string initiatedBy,
        DateTime? scheduledDate = null)
    {
        var lifecycle = await _lifecycleRepo.GetLifecycleAsync(tenantId);

        // Transition to terminating status
        await _lifecycleRepo.RecordStatusChangeAsync(
            tenantId,
            TenantStatus.Terminating,
            reason,
            initiatedBy);

        // Immediately disable tenant access
        await _accessController.DisableAccessAsync(tenantId);

        // Send offboarding notification
        await _notificationService.SendOffboardingNoticeAsync(
            tenantId, reason, scheduledDate);

        await _auditLogger.LogEventAsync(new AuditEvent
        {
            TenantId = tenantId,
            EventType = "offboarding_initiated",
            Timestamp = DateTime.UtcNow,
            Actor = initiatedBy,
            Details = new { Reason = reason, ScheduledDate = scheduledDate }
        });

        // Start offboarding workflow
        var workflowId = await StartOffboardingWorkflowAsync(
            tenantId, reason, scheduledDate);

        return new OffboardingResult
        {
            TenantId = tenantId,
            WorkflowId = workflowId,
            Status = "initiated",
            ScheduledDate = scheduledDate ?? DateTime.UtcNow
        };
    }

    private async Task<string> StartOffboardingWorkflowAsync(
        string tenantId,
        string reason,
        DateTime? scheduledDate)
    {
        // If scheduled for future, wait until scheduled date
        if (scheduledDate.HasValue && scheduledDate > DateTime.UtcNow)
        {
            await Task.Delay(scheduledDate.Value - DateTime.UtcNow);
        }

        // Execute offboarding steps
        await ExecuteOffboardingStepsAsync(tenantId, reason);

        return Guid.NewGuid().ToString();
    }

    private async Task ExecuteOffboardingStepsAsync(
        string tenantId,
        string reason)
    {
        try
        {
            // Step 1: Export tenant data
            var exportResult = await _archivalService.ExportTenantDataAsync(
                tenantId);

            await _auditLogger.LogEventAsync(new AuditEvent
            {
                TenantId = tenantId,
                EventType = "data_exported",
                Timestamp = DateTime.UtcNow,
                Actor = "system",
                Details = new
                {
                    ExportLocation = exportResult.ArchivalLocation,
                    ExportSize = exportResult.TotalSizeBytes,
                    RecordCount = exportResult.RecordCount
                }
            });

            // Step 2: Archive data to long-term storage
            var archivalResult = await _archivalService.ArchiveDataAsync(
                tenantId,
                exportResult.ExportPath,
                GetRetentionPeriod(tenantId));

            await _auditLogger.LogEventAsync(new AuditEvent
            {
                TenantId = tenantId,
                EventType = "data_archived",
                Timestamp = DateTime.UtcNow,
                Actor = "system",
                Details = new
                {
                    ArchivalLocation = archivalResult.ArchivalUri,
                    RetentionUntil = archivalResult.RetentionExpirationDate,
                    ArchiveId = archivalResult.ArchiveId
                }
            });

            // Step 3: Cleanup active resources
            await _cleanupService.CleanupTenantResourcesAsync(tenantId);

            await _auditLogger.LogEventAsync(new AuditEvent
            {
                TenantId = tenantId,
                EventType = "resources_cleaned_up",
                Timestamp = DateTime.UtcNow,
                Actor = "system",
                Details = new { Reason = "Offboarding completed" }
            });

            // Step 4: Transition to archived status
            await _lifecycleRepo.RecordStatusChangeAsync(
                tenantId,
                TenantStatus.Archived,
                "Offboarding completed successfully",
                "system");

            // Step 5: Schedule final deletion
            await ScheduleFinalDeletionAsync(
                tenantId,
                archivalResult.RetentionExpirationDate);

            // Step 6: Generate offboarding report
            await GenerateOffboardingReportAsync(
                tenantId, exportResult, archivalResult);

        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Offboarding failed for tenant {TenantId}", tenantId);

            await _auditLogger.LogEventAsync(new AuditEvent
            {
                TenantId = tenantId,
                EventType = "offboarding_failed",
                Timestamp = DateTime.UtcNow,
                Actor = "system",
                Details = new { Error = ex.Message }
            });

            throw;
        }
    }

    private TimeSpan GetRetentionPeriod(string tenantId)
    {
        // HIPAA requires minimum 6 years, most contracts specify 7-10 years
        return TimeSpan.FromDays(365 * 7); // 7 years default
    }

    private async Task ScheduleFinalDeletionAsync(
        string tenantId,
        DateTime deletionDate)
    {
        // Schedule deletion job to run after retention period
        await _schedulingService.ScheduleJobAsync(
            $"delete-tenant-{tenantId}",
            "DeleteArchivedTenantData",
            new { TenantId = tenantId },
            deletionDate);

        await _auditLogger.LogEventAsync(new AuditEvent
        {
            TenantId = tenantId,
            EventType = "deletion_scheduled",
            Timestamp = DateTime.UtcNow,
            Actor = "system",
            Details = new { ScheduledDeletionDate = deletionDate }
        });
    }
}

// DataArchivalService.cs
public class DataArchivalService : IDataArchivalService
{
    private readonly ICloudStorageService _storageService;
    private readonly IDatabaseService _databaseService;
    private readonly IEncryptionService _encryptionService;

    public async Task<ExportResult> ExportTenantDataAsync(string tenantId)
    {
        var exportPath = Path.Combine(
            Path.GetTempPath(),
            $"tenant-export-{tenantId}-{DateTime.UtcNow:yyyyMMddHHmmss}");

        Directory.CreateDirectory(exportPath);

        // Export all tenant data
        var tables = await GetTenantTablesAsync(tenantId);
        long totalRecords = 0;
        long totalBytes = 0;

        foreach (var table in tables)
        {
            var data = await _databaseService.ExportTableAsync(
                tenantId, table);

            var filePath = Path.Combine(exportPath, $"{table}.json");
            await File.WriteAllTextAsync(filePath,
                JsonSerializer.Serialize(data));

            totalRecords += data.Count;
            totalBytes += new FileInfo(filePath).Length;
        }

        return new ExportResult
        {
            ExportPath = exportPath,
            RecordCount = totalRecords,
            TotalSizeBytes = totalBytes,
            Tables = tables
        };
    }

    public async Task<ArchivalResult> ArchiveDataAsync(
        string tenantId,
        string exportPath,
        TimeSpan retentionPeriod)
    {
        // Compress export
        var archivePath = $"{exportPath}.tar.gz";
        await CompressDirectoryAsync(exportPath, archivePath);

        // Encrypt archive
        var encryptedPath = $"{archivePath}.enc";
        await _encryptionService.EncryptFileAsync(
            archivePath, encryptedPath, tenantId);

        // Upload to long-term storage (Azure Blob Archive, AWS Glacier, etc.)
        var archiveUri = await _storageService.UploadToArchiveStorageAsync(
            encryptedPath,
            $"tenant-archives/{tenantId}",
            new StorageOptions
            {
                StorageTier = "Archive", // Lowest cost, retrieval time measured in hours
                Redundancy = "GRS", // Geo-redundant storage
                Encryption = "AES256"
            });

        var retentionExpiration = DateTime.UtcNow.Add(retentionPeriod);

        // Apply retention policy
        await _storageService.SetRetentionPolicyAsync(
            archiveUri,
            retentionExpiration);

        // Cleanup local files
        Directory.Delete(exportPath, recursive: true);
        File.Delete(archivePath);
        File.Delete(encryptedPath);

        return new ArchivalResult
        {
            ArchiveId = Guid.NewGuid().ToString(),
            ArchivalUri = archiveUri,
            RetentionExpirationDate = retentionExpiration,
            ArchiveSizeBytes = new FileInfo(encryptedPath).Length
        };
    }
}

// ResourceCleanupService.cs
public class ResourceCleanupService : IResourceCleanupService
{
    private readonly IDatabaseService _databaseService;
    private readonly IInfrastructureService _infraService;
    private readonly ISecurityService _securityService;
    private readonly ILogger<ResourceCleanupService> _logger;

    public async Task CleanupTenantResourcesAsync(string tenantId)
    {
        _logger.LogInformation(
            "Starting resource cleanup for tenant {TenantId}", tenantId);

        try
        {
            // Delete tenant database (after archival)
            await _databaseService.DeleteDatabaseAsync(tenantId);
            _logger.LogInformation(
                "Database deleted for tenant {TenantId}", tenantId);

            // Revoke all access credentials
            await _securityService.RevokeAllCredentialsAsync(tenantId);
            _logger.LogInformation(
                "Credentials revoked for tenant {TenantId}", tenantId);

            // Deprovision infrastructure resources
            await _infraService.DeprovisionResourcesAsync(tenantId);
            _logger.LogInformation(
                "Infrastructure deprovisioned for tenant {TenantId}", tenantId);

            // Schedule encryption key deletion (after retention period)
            // Keys kept during retention period for potential data retrieval
            await _securityService.ScheduleKeyDeletionAsync(
                tenantId,
                TimeSpan.FromDays(365 * 7)); // Delete keys after 7 years

            _logger.LogInformation(
                "Resource cleanup completed for tenant {TenantId}", tenantId);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Resource cleanup failed for tenant {TenantId}", tenantId);
            throw;
        }
    }
}
