**Step 3.2: Implement Scheduled Deletion Service**

```csharp
// ScheduledDeletionService.cs
public class ScheduledDeletionService
{
    private readonly IDataArchivalService _archivalService;
    private readonly IAuditLogger _auditLogger;
    private readonly INotificationService _notificationService;
    private readonly TenantLifecycleRepository _lifecycleRepo;

    public async Task ExecuteScheduledDeletionAsync(string tenantId)
    {
        var lifecycle = await _lifecycleRepo.GetLifecycleAsync(tenantId);

        if (lifecycle.Status != TenantStatus.Archived)
        {
            _logger.LogWarning(
                "Skipping deletion for tenant {TenantId} - status is {Status}",
                tenantId, lifecycle.Status);
            return;
        }

        // Verify retention period has expired
        var archivalDate = lifecycle.ArchivedDate.Value;
        var retentionPeriod = TimeSpan.FromDays(365 * 7);
        var deletionEligibleDate = archivalDate.Add(retentionPeriod);

        if (DateTime.UtcNow < deletionEligibleDate)
        {
            _logger.LogWarning(
                "Tenant {TenantId} not eligible for deletion until {Date}",
                tenantId, deletionEligibleDate);
            return;
        }

        try
        {
            // Delete archived data from storage
            await _archivalService.DeleteArchivedDataAsync(tenantId);

            // Delete encryption keys
            await _securityService.DeleteEncryptionKeysAsync(tenantId);

            // Update lifecycle status
            await _lifecycleRepo.RecordStatusChangeAsync(
                tenantId,
                TenantStatus.Deleted,
                "Retention period expired, data permanently deleted",
                "system");

            // Final audit log entry
            await _auditLogger.LogEventAsync(new AuditEvent
            {
                TenantId = tenantId,
                EventType = "tenant_data_permanently_deleted",
                Timestamp = DateTime.UtcNow,
                Actor = "system",
                Details = new
                {
                    ArchivedDate = archivalDate,
                    RetentionPeriod = retentionPeriod,
                    DeletionDate = DateTime.UtcNow
                }
            });

            // Send final deletion notice
            await _notificationService.SendDeletionConfirmationAsync(tenantId);

            _logger.LogInformation(
                "Permanent deletion completed for tenant {TenantId}", tenantId);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Permanent deletion failed for tenant {TenantId}", tenantId);

            await _auditLogger.LogEventAsync(new AuditEvent
            {
                TenantId = tenantId,
                EventType = "deletion_failed",
                Timestamp = DateTime.UtcNow,
                Actor = "system",
                Details = new { Error = ex.Message }
            });

            throw;
        }
    }
}
