**Example 2: Tenant Suspension for Payment Failure**

```csharp
// PaymentFailureHandler.cs
public class PaymentFailureHandler
{
    private readonly TenantStatusWorkflowEngine _statusEngine;
    private readonly INotificationService _notificationService;

    public async Task HandlePaymentFailureAsync(
        string tenantId,
        PaymentFailureEvent paymentEvent)
    {
        // Attempt 1-3: Send payment reminders, don't suspend yet
        if (paymentEvent.AttemptNumber <= 3)
        {
            await _notificationService.SendPaymentReminderAsync(
                tenantId,
                paymentEvent.AmountDue,
                paymentEvent.DueDate);
            return;
        }

        // After 3 failed attempts, suspend tenant
        var result = await _statusEngine.TransitionStatusAsync(
            tenantId,
            TenantStatus.Suspended,
            $"Payment failure after {paymentEvent.AttemptNumber} attempts",
            "system-payment-monitor");

        if (result.Success)
        {
            // Send suspension notice
            await _notificationService.SendSuspensionNoticeAsync(
                tenantId,
                "Payment failure - account suspended",
                new
                {
                    AmountDue = paymentEvent.AmountDue,
                    AccountsReceivableContact = "ar@gainwell.com",
                    ReactivationProcess = "Contact billing to update payment method"
                });

            _logger.LogWarning(
                "Tenant {TenantId} suspended due to payment failure", tenantId);
        }
    }

    public async Task HandlePaymentRestoredAsync(string tenantId)
    {
        // Reactivate tenant after payment resolved
        var result = await _statusEngine.TransitionStatusAsync(
            tenantId,
            TenantStatus.Active,
            "Payment resolved",
            "system-payment-monitor");

        if (result.Success)
        {
            await _notificationService.SendReactivationNoticeAsync(
                tenantId,
                "Account reactivated - payment received");

            _logger.LogInformation(
                "Tenant {TenantId} reactivated after payment resolution", tenantId);
        }
    }
}
