**Example 3: Tenant Migration**

```csharp
// TenantMigrationService.cs
public class TenantMigrationService
{
    public async Task<MigrationResult> MigrateTenantToDedicatedInfrastructureAsync(
        string tenantId)
    {
        var migrationPlan = new MigrationPlan
        {
            TenantId = tenantId,
            SourceEnvironment = "shared-infrastructure",
            TargetEnvironment = "dedicated-infrastructure",
            MigrationDate = DateTime.UtcNow,
            EstimatedDowntime = TimeSpan.FromMinutes(5) // DNS cutover only
        };

        try
        {
            // Phase 1: Provision dedicated infrastructure
            await ProvisionDedicatedInfrastructureAsync(tenantId);

            // Phase 2: Initial data sync (while tenant still active on source)
            await SyncDataAsync(
                source: migrationPlan.SourceEnvironment,
                target: migrationPlan.TargetEnvironment,
                tenantId: tenantId);

            // Phase 3: Enable maintenance mode
            await _statusEngine.TransitionStatusAsync(
                tenantId,
                TenantStatus.Maintenance,
                "Migration to dedicated infrastructure in progress",
                "migration-service");

            // Phase 4: Final data sync
            await SyncDataAsync(
                source: migrationPlan.SourceEnvironment,
                target: migrationPlan.TargetEnvironment,
                tenantId: tenantId,
                incrementalOnly: true);

            // Phase 5: Update routing/DNS
            await UpdateTenantRoutingAsync(
                tenantId,
                migrationPlan.TargetEnvironment);

            // Phase 6: Validate migration
            var validationResult = await ValidateMigrationAsync(
                tenantId,
                migrationPlan);

            if (!validationResult.Success)
            {
                // Rollback if validation fails
                await RollbackMigrationAsync(tenantId, migrationPlan);
                throw new MigrationException(
                    $"Migration validation failed: {validationResult.Error}");
            }

            // Phase 7: Reactivate tenant on new infrastructure
            await _statusEngine.TransitionStatusAsync(
                tenantId,
                TenantStatus.Active,
                "Migration completed successfully",
                "migration-service");

            // Phase 8: Cleanup old infrastructure (after 24-hour grace period)
            await ScheduleSourceCleanupAsync(
                tenantId,
                migrationPlan.SourceEnvironment,
                TimeSpan.FromHours(24));

            return MigrationResult.Success(migrationPlan);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Migration failed for tenant {TenantId}", tenantId);
            return MigrationResult.Failure(ex.Message);
        }
    }
}
